// @ts-nocheck
globalThis.addEventListener("beforeprint",e=>{document.querySelectorAll("input[type='submit'], input[type='button']").forEach(e=>e.hide()),document.getElementById("leftMenu").hide()}),globalThis.addEventListener("afterprint",e=>{document.querySelectorAll("input[type='submit'], input[type='button']").forEach(e=>e.show()),document.getElementById("leftMenu").show()});